INSERT INTO `wp_trustindex_google_reviews` (`id`, `hidden`, `user`, `user_photo`, `text`, `rating`, `highlight`, `date`, `reviewId`, `reply`) VALUES
(1, 0, 'Joey burleyson', 'https://lh3.googleusercontent.com/a-/ALV-UjVoHhBhi3-bTpBrXPoDYi3Z6VSYO2rH5nSRTtqgRvTVsjccaZ0=s120-c-rp-mo-br100', 'A wonderful experience as always. Robin made everything happen to take care of me and got me set up. Knowledgeable, friendly, and fair prices every time I’m in the store. I recommend Mata’s for any firearms needs.', 5.0, NULL, '2026-01-08', 'Ci9DQUlRQUNvZENodHljRjlvT21sZlpETjFPVVprV0VsUFVHTjJUbXBsVVhVdFFYYxAB', ''),
(2, 0, 'MrGrun0n', 'https://lh3.googleusercontent.com/a/ACg8ocLwZDq2Be0wTCttsyNVN7QW9-RiH6RwsCw2CSJ2J3s8Vh6I7A=s120-c-rp-mo-br100', NULL, 5.0, NULL, '2026-01-04', 'Ci9DQUlRQUNvZENodHljRjlvT2pnelVWcHdiV3RwWjJsZmJERjFVakJwVm5wM1VGRRAB', ''),
(3, 0, 'Ryan Blair', 'https://lh3.googleusercontent.com/a/ACg8ocJ74dA8x1TTCBg9FuH9BCxzE8wYgNNS6gLgp8gXcjwiVi4wuw=s120-c-rp-mo-br100', 'Super nice guys! High quality options! Stop in and check it out!', 5.0, NULL, '2026-01-03', 'Ci9DQUlRQUNvZENodHljRjlvT2tSMGIzQkpSMmQyTkZscFNHdFpRa0pyYkdoT1JFRRAB', 'Thank you for checking out the shop!'),
(4, 0, 'Joey Burleyson', 'https://lh3.googleusercontent.com/a/ACg8ocJ8roYeVkzOZDJAvMCJwE1R0071vBnTOCJojolbIkngiMd6og=s120-c-rp-mo-br100', 'Great people with good prices. Casper, Nick, and Jason did such a great job with my firearm purchase I bought a second one.', 5.0, NULL, '2025-12-18', 'Ci9DQUlRQUNvZENodHljRjlvT2xnM1VHZDViVFpGZFZGSGJFOUlUbTVqTlZCSGIzYxAB', ''),
(5, 0, 'Eduardo Moniet', 'https://lh3.googleusercontent.com/a-/ALV-UjWMcjZ72vJ7vnAq9iVppn5ehl3fB_LQTsQCzoBsaKIwk7LM1bQI=s120-c-rp-mo-br100', 'Mata\'s tactical supply is my new GO TO for suppressors and ammo. They made the process super easy and painless even over the phone.  The wife LOVED the cute boutique stores also!', 5.0, NULL, '2025-12-12', 'Ci9DQUlRQUNvZENodHljRjlvT21oNGVEVlRja1JRVlVkbFZub3hkbE5CTlVkNWRGRRAB', 'Thank you for coming all the way from South Texas to do your paperwork with MTS'),
(6, 0, 'John Pugh', 'https://lh3.googleusercontent.com/a/ACg8ocKsGsy7Esm_tSKklkVAO0pokNrTCb3y-yKxnuD3hsolotzdjQ=s120-c-rp-mo-br100', 'If your looking to buy a firearm or accessories look no further. The folks at Mata\'s Tactical are the best around. The staff is friendy and very knowledgeable about their products. If they dont have what your looking for they can get it for you. I can\'t say enough about how great these folks are.', 5.0, NULL, '2025-11-11', 'Ci9DQUlRQUNvZENodHljRjlvT2xnek1WaFZVSGhtYkdWcWNrZHdlVWh6TW5kcFQxRRAB', ''),
(7, 0, 'Chuck Rokohl', 'https://lh3.googleusercontent.com/a/ACg8ocJCSwp99vh9VO3zEaroqWSBArq8Gndh8WFvJLBHj0SA4SVrEA=s120-c-rp-mo-br100', NULL, 2.0, NULL, '2025-10-21', 'Ci9DQUlRQUNvZENodHljRjlvT2poV04zZFBVM1IyVGtOdlp6aHRUV2h6ZFdsdWRFRRAB', ''),
(8, 0, 'Brade Mcbride', 'https://lh3.googleusercontent.com/a/ACg8ocL6krsp9w83SbucVbfAPvh2vqTmzqFkoOT-uXoY_083K41alQ=s120-c-rp-mo-br100', 'Great service all that work there are very helpful and very informative', 5.0, NULL, '2025-10-01', 'Ci9DQUlRQUNvZENodHljRjlvT21sYVkyZGZhMlJ6YTBzeGEydzFVSGt0TW01aVkwRRAB', ''),
(9, 0, 'Bryan Krenke', 'https://lh3.googleusercontent.com/a/ACg8ocKuzd0I2Di6Tz8u5WKyzEP8-LA-2RRKEbMtmx1zYzIPXr0iFA=s120-c-rp-mo-br100', 'Bobby is the man! Awesome webinars. Have told so many people about them I feel like a spokesperson for MATA lol. Hoping to visit the store one day if I can ever make it down there.', 5.0, NULL, '2025-08-21', 'Ci9DQUlRQUNvZENodHljRjlvT21kaWMwcFJOMVZmTjBNNE1VdHNWMnBPTFhOYVUwRRAB', 'Thank you so much. If you are ever down here, I would love to shake your hand'),
(10, 0, 'Tabbie Pegoda', 'https://lh3.googleusercontent.com/a-/ALV-UjWsYMC70SQbbbxzA15c3aCW8PTJElf3zkfjdKtSng_rEfusR78r=s120-c-rp-mo-br100', 'Mata’s Tactical Supply is top notch in every possible way! I have requested several firearms for my husband for gifts and they went out of their way to find them! Bobby is so gracious and kind. If youre going to make this type of purchase this is THE place to do it!', 5.0, NULL, '2025-08-15', 'ChdDSUhNMG9nS0VJQ0FnSUNua3NpUjV3RRAB', '');
